using System.ComponentModel;
using Microsoft.Extensions.AI;
using OpenAI;

var topic = args.Length > 0 ? string.Join(' ', args) : "quantum computing recent breakthroughs";

Console.WriteLine($"Research Agent Starting...");
Console.WriteLine($"Topic: {topic}");
Console.WriteLine();

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY") ?? "sk-placeholder";
var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

var openAiClient = new OpenAIClient(apiKey);
IChatClient chatClient = openAiClient.GetChatClient(model)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

var notes = new ResearchNotes();

var chatOptions = new ChatOptions
{
    Tools =
    [
        AIFunctionFactory.Create(
            (string query) => WebSearchTool.SearchAsync(query),
            "web_search",
            "Searches the web for information on a given query and returns relevant results."),
        AIFunctionFactory.Create(
            ([Description("The note text to save")] string note) => notes.AddNote(note),
            "take_note",
            "Saves an important finding or piece of information for later summarization."),
        AIFunctionFactory.Create(
            () => notes.GetAllNotes(),
            "get_notes",
            "Retrieves all notes taken so far during the research session.")
    ]
};

var messages = new List<ChatMessage>
{
    new(ChatRole.System, """
        You are a research agent. Your job is to research a topic thoroughly by:
        1. Searching the web for relevant information using multiple queries
        2. Taking notes on key findings as you discover them
        3. After gathering enough information, reviewing your notes and providing a comprehensive summary

        Always take notes on important findings before moving to the next search.
        Perform at least 3 different searches to get a well-rounded view of the topic.
        When you have enough information, retrieve your notes and write a final summary.
        """),
    new(ChatRole.User, $"Please research the following topic and provide a summary: {topic}")
};

Console.WriteLine("Agent is researching...");
Console.WriteLine();

var response = await chatClient.GetResponseAsync(messages, chatOptions);

Console.WriteLine("=== Research Summary ===");
Console.WriteLine();
Console.WriteLine(response.Text);
Console.WriteLine();
Console.WriteLine($"--- Notes collected: {notes.Count} ---");
foreach (var note in notes.AllNotes)
{
    Console.WriteLine($"  • {note}");
}

// --- Tool Implementations ---

public static class WebSearchTool
{
    private static readonly HttpClient Http = new();

    public static async Task<string> SearchAsync(string query)
    {
        Console.WriteLine($"  [Searching: \"{query}\"]");

        // Use a public search API if available, otherwise return simulated results
        var searchApiUrl = Environment.GetEnvironmentVariable("SEARCH_API_URL");
        if (!string.IsNullOrEmpty(searchApiUrl))
        {
            try
            {
                var encodedQuery = Uri.EscapeDataString(query);
                var result = await Http.GetStringAsync($"{searchApiUrl}?q={encodedQuery}");
                return result.Length > 2000 ? result[..2000] : result;
            }
            catch (Exception ex)
            {
                return $"Search failed: {ex.Message}. Query was: {query}";
            }
        }

        // Simulated search results for demonstration
        return $"""
            Search results for: "{query}"

            1. [Research Article] Recent developments related to {query} show significant progress 
               in the field. Multiple research teams have published findings in 2025-2026.

            2. [News] Industry experts predict that {query} will see major advances in the 
               coming years, with applications in healthcare, energy, and computing.

            3. [Academic Paper] A comprehensive review of {query} highlights key challenges 
               and opportunities, noting that collaboration between institutions has accelerated progress.

            4. [Technology Report] Current state of {query} indicates growing investment 
               from both public and private sectors, with several pilot programs underway.
            """;
    }
}

public class ResearchNotes
{
    private readonly List<string> _notes = [];

    public int Count => _notes.Count;
    public IReadOnlyList<string> AllNotes => _notes;

    public string AddNote(string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  [Note saved: \"{note[..Math.Min(note.Length, 60)]}...\"]");
        return $"Note saved. Total notes: {_notes.Count}";
    }

    public string GetAllNotes()
    {
        if (_notes.Count == 0)
            return "No notes taken yet.";

        return string.Join("\n", _notes.Select((n, i) => $"{i + 1}. {n}"));
    }
}

